import { test, expect } from '@playwright/test';

test.describe('Internal Links Open in Same Tab', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should open internal links in the same tab', async ({ page }) => {
    // Verify initial page content
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();

    const navLink = page.getByRole('navigation').first();
    await expect(navLink).toBeVisible();

    // Click on an internal link
    const aboutLink = page.getByRole('link', { name: /about/i });
    await expect(aboutLink).toBeVisible();
    await aboutLink.click();

    // Verify about page content is visible
    const aboutContent = page.getByText(/about us/i);
    await expect(aboutContent).toBeVisible();

    // Verify URL remains the same
    const currentUrl = page.url();
    await expect(currentUrl).toContain('/');

    // Verify navigation is not duplicated
    const navLinkCount = page.getByRole('navigation').count();
    await expect(navLinkCount).toBe(1);

    // Verify back button navigates to home
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();
    await backButton.click();

    // Verify home page content is visible
    const homeContent = page.getByText(/home/i);
    await expect(homeContent).toBeVisible();

    // Verify URL is still the same
    const homeUrl = page.url();
    await expect(homeUrl).toContain('/');

    // Verify navigation is not duplicated
    const navLinkCount = page.getByRole('navigation').count();
    await expect(navLinkCount).toBe(1);
  });

  test('should handle deep internal links and maintain tab focus', async ({ page }) => {
    // Navigate to a deep internal link
    const deepLink = page.getByRole('link', { name: /deep link/i });
    await expect(deepLink).toBeVisible();
    await deepLink.click();

    // Verify deep link content is visible
    const deepContent = page.getByText(/deep link content/i);
    await expect(deepContent).toBeVisible();

    // Verify URL remains the same
    const deepUrl = page.url();
    await expect(deepUrl).toContain('/deep-link');

    // Verify navigation is not duplicated
    const navLinkCount = page.getByRole('navigation').count();
    await expect(navLinkCount).toBe(1);

    // Verify tab focus is maintained
    const tabFocus = page.getByRole('tab');
    await expect(tabFocus).toBeVisible();

    // Verify back button navigates to previous page
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();
    await backButton.click();

    // Verify home page content is visible
    const homeContent = page.getByText(/home/i);
    await expect(homeContent).toBeVisible();

    // Verify URL is still the same
    const homeUrl = page.url();
    await expect(homeUrl).toContain('/');

    // Verify navigation is not duplicated
    const navLinkCount = page.getByRole('navigation').count();
    await expect(navLinkCount).toBe(1);
  });
});
